public sealed partial class MixerParameter {
 public static MixerParameter OutputPatch(int group,int port){if(group<0||group>8||port<0||port>=(group<6?16:group==6?8:group==7?6:2))throw new ArgumentOutOfRangeException();return new MixerParameter(6,2,group<6?5:group==6?6:group==7?12:13,group<6?port:0,group<6?group:port,0,group<7?164:group==7?158:106);}
 public static MixerParameter Route(int channel,int destination){if(channel<0||channel>95||destination<0||destination>10)throw new ArgumentOutOfRangeException();return new MixerParameter(127,1,34,destination,channel,0,1);}
}
public sealed partial class FaderConnection {
 readonly Queue<MixerParameter> routingReads=new Queue<MixerParameter>();readonly Dictionary<ulong,Scalar> routingValues=new Dictionary<ulong,Scalar>();
 MixerParameter routingWrite;int routingTarget,routingBaseline,routingPhase;double routingDeadline,nextRouting;public string RoutingStatus{get{lock(gate)return routingStatus;}}string routingStatus="";
 public void ReadRouting(IEnumerable<MixerParameter> parameters){lock(gate){foreach(var p in parameters){Register(p);routingValues.Remove(p.Key);routingReads.Enqueue(p);}}}
 public int? RoutingValue(MixerParameter p){lock(gate){Scalar value;return routingValues.TryGetValue(p.Key,out value)?(int?)value.Value:null;}}
 public bool RoutingBusy{get{lock(gate)return routingWrite!=null;}}
 public void WriteRouting(MixerParameter p,int expected,int target){lock(gate){if(stopping||error!=null||routingWrite!=null)throw new InvalidOperationException("Wait for the current connection change to finish.");p.Write(target,device);int? current=RoutingValue(p);if(current!=expected)throw new InvalidOperationException("Read this connection from the desk again before changing it.");Register(p);routingWrite=p;routingBaseline=expected;routingTarget=target;routingPhase=0;routingStatus="Checking current desk connection…";}}
 void RoutingPacket(MixerParameter p,int value){routingValues[p.Key]=new Scalar{Value=value,Time=DateTime.UtcNow};if(routingWrite==null||routingWrite.Key!=p.Key)return;if(routingPhase==1){if(value!=routingBaseline){routingStatus="The connection changed on the desk. Read it again before applying.";routingWrite=null;}else routingPhase=2;}else if(routingPhase==3&&value==routingTarget){if(IsStartupParameter(p))lock(startupGate)startupSnapshot[p.Key]=value;routingStatus="Connection confirmed by the desk.";routingWrite=null;}}
 void TickRouting(FaderReader output,double now){if(routingWrite!=null){if(routingPhase==0){routingPhase=1;routingDeadline=now+2000;output.ReadParameter(routingWrite,device);}else if(routingPhase==2){output.SetParameter(routingWrite,routingTarget,device);routingPhase=4;routingDeadline=now+2000;nextRouting=now+40;}else if(routingPhase==4&&now>=nextRouting){routingPhase=3;output.ReadParameter(routingWrite,device);nextRouting=now+150;}else if(routingPhase==3&&now>=nextRouting){output.ReadParameter(routingWrite,device);nextRouting=now+150;}if(routingWrite!=null&&now>routingDeadline){routingStatus="Desk confirmation timed out. Read the connection again to check its state.";routingWrite=null;}}else if(routingReads.Count>0&&now>=nextRouting){for(int i=0;i<2&&routingReads.Count>0;i++)output.ReadParameter(routingReads.Dequeue(),device);nextRouting=now+15;}}
}

sealed class PatchChoice {public int Value;public string Label;public override string ToString(){return Label;}}
sealed class SignalFlow : Control {
