 public SignalFlow(){DoubleBuffered=true;Height=190;Dock=DockStyle.Top;}
 protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);int w=Math.Max(110,(Width-100)/3);string[] titles={"SOURCE",Channel,"DESTINATIONS"};string[] bodies={Source,"Channel processing\nFader / pan",Destinations};for(int i=0;i<3;i++){Rectangle box=new Rectangle(10+i*(w+35),20,w,145);using(var b=new SolidBrush(Color.FromArgb(38,47,58)))e.Graphics.FillRectangle(b,box);using(var pen=new Pen(Color.FromArgb(84,180,208),2)){e.Graphics.DrawRectangle(pen,box);if(i<2){int x=box.Right+4,y=90;e.Graphics.DrawLine(pen,x,y,x+25,y);e.Graphics.DrawLine(pen,x+25,y,x+19,y-5);e.Graphics.DrawLine(pen,x+25,y,x+19,y+5);}}TextRenderer.DrawText(e.Graphics,titles[i],Font,new Rectangle(box.X+10,box.Y+10,w-20,25),ForeColor);TextRenderer.DrawText(e.Graphics,bodies[i],Font,new Rectangle(box.X+10,box.Y+40,w-20,100),ForeColor,TextFormatFlags.WordBreak);}}
}
sealed class RoutingWindow : Form {
 public static void Test(){using(var log=new StreamWriter(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"routing-test.txt"))){log.AutoFlush=true;using(var c=FeatureTests.Open()){var parameters=new List<MixerParameter>();for(int i=0;i<96;i++)parameters.Add(MixerParameter.InputSource(i));for(int g=0;g<9;g++)for(int i=0;i<(g<6?16:g==6?8:g==7?6:2);i++)parameters.Add(MixerParameter.OutputPatch(g,i));for(int i=0;i<11;i++)parameters.Add(MixerParameter.Route(0,i));c.ReadRouting(parameters);DateTime end=DateTime.UtcNow.AddSeconds(7);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}var missing=new List<MixerParameter>();foreach(var p in parameters)if(!c.RoutingValue(p).HasValue)missing.Add(p);if(missing.Count>0){c.ReadRouting(missing);System.Threading.Thread.Sleep(2500);}foreach(var p in parameters)if(!c.RoutingValue(p).HasValue){log.WriteLine("Missing routing readback: "+p.Element+"/"+p.Index+"/"+p.Channel+" error="+c.Error);throw new Exception("Missing routing readback");}log.WriteLine("PASS: all 96 input patches, 112 output patches and selected input destinations read.");foreach(var p in new MixerParameter[]{MixerParameter.InputSource(0),MixerParameter.OutputPatch(2,0),MixerParameter.OutputPatch(6,0),MixerParameter.OutputPatch(7,0),MixerParameter.OutputPatch(8,0),MixerParameter.Route(0,0)}){int value=c.RoutingValue(p).Value;c.WriteRouting(p,value,value);end=DateTime.UtcNow.AddSeconds(3);while(c.RoutingBusy&&DateTime.UtcNow<end)System.Threading.Thread.Sleep(10);if(c.RoutingBusy||c.RoutingStatus!="Connection confirmed by the desk.")throw new Exception(c.RoutingStatus);log.WriteLine("PASS: same-value write confirmed for "+p.Element+"/"+p.Index+"/"+p.Channel);}using(var window=new RoutingWindow(delegate{return c;},24)){window.Show();end=DateTime.UtcNow.AddSeconds(2);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}foreach(int g in new int[]{0,2,6,7,8}){window.groups.SelectedIndex=g;Application.DoEvents();}window.groups.SelectedIndex=2;end=DateTime.UtcNow.AddSeconds(1);while(DateTime.UtcNow<end){Application.DoEvents();System.Threading.Thread.Sleep(10);}int? loadedInput=window.inputValue,loadedOutput=window.outputValue;if(!loadedInput.HasValue||!loadedOutput.HasValue)throw new Exception("Routing UI data missing");using(var image=new Bitmap(window.Width,window.Height)){window.DrawToBitmap(image,new Rectangle(Point.Empty,window.Size));image.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"routing-window.png"));}window.Close();log.WriteLine("PASS: routing window loads, switches output families and renders live data.");}}}}
 readonly Func<FaderConnection> connection;FaderConnection active;ComboBox inputs=new ComboBox(),sources=new ComboBox(),groups=new ComboBox(),ports=new ComboBox(),outputs=new ComboBox();Label inputCurrent=new Label(),outputCurrent=new Label(),status=new Label();Button applyInput=new Button(),applyOutput=new Button();SignalFlow flow=new SignalFlow();static readonly string[] destinationNames={"Stereo","Follow pan","Direct out","Bus 1","Bus 2","Bus 3","Bus 4","Bus 5","Bus 6","Bus 7","Bus 8"};Timer timer=new Timer();int? inputValue,outputValue;bool loading;
 public RoutingWindow(Func<FaderConnection> get,int selected){connection=get;Text="DM2000 · Routing & signal flow";Size=new Size(1100,760);MinimumSize=new Size(760,620);BackColor=Color.FromArgb(21,25,31);ForeColor=Color.FromArgb(225,233,243);Font=new Font("Segoe UI",10);var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(18),ColumnCount=1,RowCount=5};root.RowStyles.Add(new RowStyle(SizeType.Absolute,45));root.RowStyles.Add(new RowStyle(SizeType.Absolute,190));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,40));root.RowStyles.Add(new RowStyle(SizeType.Absolute,35));Controls.Add(root);var top=new FlowLayoutPanel{Dock=DockStyle.Fill};top.Controls.Add(new Label{Text="Follow input",AutoSize=true,Padding=new Padding(0,7,10,0)});for(int i=0;i<96;i++)inputs.Items.Add("Input "+(i+1));Style(inputs,140);top.Controls.Add(inputs);var read=new Button{Text="Read from desk",AutoSize=true};top.Controls.Add(read);root.Controls.Add(top,0,0);root.Controls.Add(flow,0,1);var tabs=new TabControl{Dock=DockStyle.Fill};root.Controls.Add(tabs,0,2);var inputTab=new TabPage("Input patch"){BackColor=BackColor,ForeColor=ForeColor};var outputTab=new TabPage("Output patch"){BackColor=BackColor,ForeColor=ForeColor};tabs.TabPages.AddRange(new TabPage[]{inputTab,outputTab});var ip=Stack(inputTab);Add(ip,"Connect a source to the selected input",inputCurrent);Style(sources,480);for(int i=0;i<179;i++)sources.Items.Add(new PatchChoice{Value=i,Label=InputSources.Label(i,true)});ip.Controls.Add(sources);applyInput.Text="Apply input connection";applyInput.AutoSize=true;ip.Controls.Add(applyInput);var op=Stack(outputTab);Add(op,"Connect a desk signal to a physical output",outputCurrent);Style(groups,230);for(int i=0;i<6;i++)groups.Items.Add("Slot "+(i+1));groups.Items.AddRange(new object[]{"Omni outputs","2TR digital outputs","Stereo outputs"});Style(ports,190);Style(outputs,480);op.Controls.Add(groups);op.Controls.Add(ports);op.Controls.Add(outputs);applyOutput.Text="Apply output connection";applyOutput.AutoSize=true;op.Controls.Add(applyOutput);root.Controls.Add(new Label{Text="Flow shows routing stages. Channel processing is grouped; insert and processing order are not expanded.",Dock=DockStyle.Fill},0,3);status.Dock=DockStyle.Fill;root.Controls.Add(status,0,4);
 inputs.SelectedIndexChanged+=delegate{ReadInput();};groups.SelectedIndexChanged+=delegate{BuildOutputs();};ports.SelectedIndexChanged+=delegate{ReadOutput();};read.Click+=delegate{ReadInput();ReadOutput();};applyInput.Click+=delegate{Apply(MixerParameter.InputSource(inputs.SelectedIndex),inputValue,sources);};applyOutput.Click+=delegate{Apply(OutputParameter(),outputValue,outputs);};inputs.SelectedIndex=Math.Max(0,Math.Min(95,selected));groups.SelectedIndex=0;timer.Interval=100;timer.Tick+=delegate{RefreshDesk();};timer.Start();FormClosed+=delegate{timer.Dispose();};}
 static void Style(ComboBox c,int width){c.DropDownStyle=ComboBoxStyle.DropDownList;c.BackColor=Color.FromArgb(38,47,58);c.ForeColor=Color.FromArgb(225,233,243);c.FlatStyle=FlatStyle.Flat;c.DrawMode=DrawMode.OwnerDrawFixed;c.DrawItem+=delegate(object sender,DrawItemEventArgs e){using(var brush=new SolidBrush(Color.FromArgb(38,47,58)))e.Graphics.FillRectangle(brush,e.Bounds);if(e.Index>=0)TextRenderer.DrawText(e.Graphics,c.Items[e.Index].ToString(),c.Font,e.Bounds,Color.FromArgb(225,233,243),TextFormatFlags.Left|TextFormatFlags.VerticalCenter);e.DrawFocusRectangle();};c.Width=width;c.Margin=new Padding(0,8,12,8);}
 static FlowLayoutPanel Stack(Control parent){var p=new FlowLayoutPanel{Dock=DockStyle.Fill,FlowDirection=FlowDirection.TopDown,WrapContents=false,AutoScroll=true,Padding=new Padding(18)};parent.Controls.Add(p);return p;}
 static void Add(FlowLayoutPanel panel,string title,Label value){panel.Controls.Add(new Label{Text=title,AutoSize=true});value.AutoSize=true;value.Margin=new Padding(0,12,0,8);panel.Controls.Add(value);}
 MixerParameter OutputParameter(){return groups.SelectedIndex<0||ports.SelectedIndex<0?null:MixerParameter.OutputPatch(groups.SelectedIndex,ports.SelectedIndex);}
 void BuildOutputs(){loading=true;ports.Items.Clear();int g=groups.SelectedIndex,n=g<6?16:g==6?8:g==7?6:2;for(int i=0;i<n;i++)ports.Items.Add(g==7?"Digital "+(i/2+1)+(i%2==0?" L":" R"):g==8?(i==0?"Stereo L":"Stereo R"):"Output "+(i+1));outputs.Items.Clear();string file=g<6?"slot":g==6?"omni":g==7?"digital":"stereo";foreach(string line in File.ReadAllLines(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"routing-"+file+".tsv"))){var parts=line.Split('\t');int v=int.Parse(parts[0]);if(v<=(g<7?164:g==7?158:106))outputs.Items.Add(new PatchChoice{Value=v,Label=parts[1]});}ports.SelectedIndex=0;loading=false;ReadOutput();}
 void ReadInput(){inputValue=null;var c=connection();if(c==null||inputs.SelectedIndex<0)return;var list=new List<MixerParameter>{MixerParameter.InputSource(inputs.SelectedIndex)};for(int i=0;i<11;i++)list.Add(MixerParameter.Route(inputs.SelectedIndex,i));c.ReadRouting(list);}
 void ReadOutput(){if(loading)return;outputValue=null;var c=connection();var p=OutputParameter();if(c!=null&&p!=null)c.ReadRouting(new MixerParameter[]{p});}
 void Apply(MixerParameter p,int? current,ComboBox list){try{var c=connection();var choice=list.SelectedItem as PatchChoice;if(c==null||p==null||!current.HasValue||choice==null)throw new Exception("Wait for desk data and choose a connection.");c.WriteRouting(p,current.Value,choice.Value);}catch(Exception ex){MessageBox.Show(this,ex.Message,"Routing",MessageBoxButtons.OK,MessageBoxIcon.Information);}}
 static void SelectValue(ComboBox box,int value){for(int i=0;i<box.Items.Count;i++)if(((PatchChoice)box.Items[i]).Value==value){box.SelectedIndex=i;return;}box.SelectedIndex=-1;}
 void RefreshDesk(){var c=connection();if(c!=active){active=c;ReadInput();ReadOutput();}bool available=c!=null&&c.Error==null;if(!available){status.Text="Connect the mixer to view and edit routing.";applyInput.Enabled=applyOutput.Enabled=false;return;}int id=inputs.SelectedIndex;int? iv=c.RoutingValue(MixerParameter.InputSource(id));var p=OutputParameter();int? ov=p==null?null:c.RoutingValue(p);if(iv!=inputValue){inputValue=iv;if(iv.HasValue)SelectValue(sources,iv.Value);}if(ov!=outputValue){outputValue=ov;if(ov.HasValue)SelectValue(outputs,ov.Value);}inputCurrent.Text=iv.HasValue?"Desk source: "+InputSources.Label(iv.Value,true):"Reading source…";outputCurrent.Text=ov.HasValue?"Desk signal: "+OutputLabel(ov.Value):"Reading output…";var destinations=new List<string>();for(int i=0;i<11;i++){int? v=c.RoutingValue(MixerParameter.Route(id,i));if(v==1&&i!=1)destinations.Add(destinationNames[i]);}flow.Source=iv.HasValue?InputSources.Label(iv.Value,true):"Reading…";flow.Channel="INPUT "+(id+1);flow.Destinations=destinations.Count>0?string.Join(" · ",destinations.ToArray()):"No destinations / waiting for data";flow.Invalidate();bool outputAvailable=true;if(groups.SelectedIndex<6){var card=c.Card(groups.SelectedIndex);outputAvailable=card.Complete&&ports.SelectedIndex<card.Outputs;if(!outputAvailable)outputCurrent.Text+=" · No physical output detected at this port";}applyInput.Enabled=inputValue.HasValue&&!c.RoutingBusy;applyOutput.Enabled=outputValue.HasValue&&outputAvailable&&!c.RoutingBusy;status.Text=c.RoutingStatus;}
 string OutputLabel(int value){foreach(PatchChoice choice in outputs.Items)if(choice.Value==value)return choice.Label;return "Value "+value;}
}
